EncodableList ClassicDeviceMessage::ToEncodableList() const {
  EncodableList list;
  list.reserve(5);
  list.push_back(EncodableValue(device_id_));
  list.push_back(name_ ? EncodableValue(*name_) : EncodableValue());
  list.push_back(rssi_ ? EncodableValue(*rssi_) : EncodableValue());
  list.push_back(device_class_ ? EncodableValue(*device_class_) : EncodableValue());
  list.push_back(CustomEncodableValue(bond_state_));
  return list;
}

ClassicDeviceMessage ClassicDeviceMessage::FromEncodableList(const EncodableList& list) {
  ClassicDeviceMessage decoded(
    std::get<std::string>(list[0]),
    std::any_cast<const BondStateMessage&>(std::get<CustomEncodableValue>(list[4])));
  auto& encodable_name = list[1];
  if (!encodable_name.IsNull()) {
    decoded.set_name(std::get<std::string>(encodable_name));
  }
  auto& encodable_rssi = list[2];
  if (!encodable_rssi.IsNull()) {
    decoded.set_rssi(std::get<int64_t>(encodable_rssi));
  }
  auto& encodable_device_class = list[3];
  if (!encodable_device_class.IsNull()) {
    decoded.set_device_class(std::get<int64_t>(encodable_device_class));
  }
  return decoded;
}

bool ClassicDeviceMessage::operator==(const ClassicDeviceMessage& other) const {
  return PigeonInternalDeepEquals(device_id_, other.device_id_) && PigeonInternalDeepEquals(name_, other.name_) && PigeonInternalDeepEquals(rssi_, other.rssi_) && PigeonInternalDeepEquals(device_class_, other.device_class_) && PigeonInternalDeepEquals(bond_state_, other.bond_state_);
}

bool ClassicDeviceMessage::operator!=(const ClassicDeviceMessage& other) const {
  return !(*this == other);
}

size_t ClassicDeviceMessage::Hash() const {
  size_t result = 1;
  result = result * 31 + PigeonInternalDeepHash(device_id_);
  result = result * 31 + PigeonInternalDeepHash(name_);
  result = result * 31 + PigeonInternalDeepHash(rssi_);
  result = result * 31 + PigeonInternalDeepHash(device_class_);
  result = result * 31 + PigeonInternalDeepHash(bond_state_);
  return result;
}

