PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<AdapterStateMessage>(enum_arg_value));
      }
    case 130: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<PermissionStatusMessage>(enum_arg_value));
      }
    case 131: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ScanModeMessage>(enum_arg_value));
      }
    case 132: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ConnectionStateMessage>(enum_arg_value));
      }
    case 133: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ConnectionPriorityMessage>(enum_arg_value));
      }
    case 134: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<PhyMessage>(enum_arg_value));
      }
    case 135: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<BondStateMessage>(enum_arg_value));
      }
    case 136: {
        return CustomEncodableValue(CapabilitiesMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 137: {
        return CustomEncodableValue(ScanSettingsMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 138: {
        return CustomEncodableValue(ScanResultMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 139: {
        return CustomEncodableValue(SystemDeviceMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 140: {
        return CustomEncodableValue(CharacteristicPropertiesMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 141: {
        return CustomEncodableValue(DescriptorMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 142: {
        return CustomEncodableValue(CharacteristicMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 143: {
        return CustomEncodableValue(ServiceMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 144: {
        return CustomEncodableValue(CharacteristicAddressMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 145: {
        return CustomEncodableValue(CharacteristicValueMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 146: {
        return CustomEncodableValue(PlatformErrorMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 147: {
        return CustomEncodableValue(ClassicDeviceMessage::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(AdapterStateMessage)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<AdapterStateMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(PermissionStatusMessage)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<PermissionStatusMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(ScanModeMessage)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ScanModeMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(ConnectionStateMessage)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ConnectionStateMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(ConnectionPriorityMessage)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ConnectionPriorityMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(PhyMessage)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<PhyMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(BondStateMessage)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<BondStateMessage>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(CapabilitiesMessage)) {
      stream->WriteByte(136);
      WriteValue(EncodableValue(std::any_cast<CapabilitiesMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ScanSettingsMessage)) {
      stream->WriteByte(137);
      WriteValue(EncodableValue(std::any_cast<ScanSettingsMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ScanResultMessage)) {
      stream->WriteByte(138);
      WriteValue(EncodableValue(std::any_cast<ScanResultMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(SystemDeviceMessage)) {
      stream->WriteByte(139);
      WriteValue(EncodableValue(std::any_cast<SystemDeviceMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CharacteristicPropertiesMessage)) {
      stream->WriteByte(140);
      WriteValue(EncodableValue(std::any_cast<CharacteristicPropertiesMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(DescriptorMessage)) {
      stream->WriteByte(141);
      WriteValue(EncodableValue(std::any_cast<DescriptorMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CharacteristicMessage)) {
      stream->WriteByte(142);
      WriteValue(EncodableValue(std::any_cast<CharacteristicMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ServiceMessage)) {
      stream->WriteByte(143);
      WriteValue(EncodableValue(std::any_cast<ServiceMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CharacteristicAddressMessage)) {
      stream->WriteByte(144);
      WriteValue(EncodableValue(std::any_cast<CharacteristicAddressMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CharacteristicValueMessage)) {
      stream->WriteByte(145);
      WriteValue(EncodableValue(std::any_cast<CharacteristicValueMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformErrorMessage)) {
      stream->WriteByte(146);
      WriteValue(EncodableValue(std::any_cast<PlatformErrorMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ClassicDeviceMessage)) {
      stream->WriteByte(147);
      WriteValue(EncodableValue(std::any_cast<ClassicDeviceMessage>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

